-- Generated by scripts/emit-sql.ts. Replaces the demo catalog.
BEGIN;
TRUNCATE products;
INSERT INTO products (
  id, slug, name, category, price_cents, summary, description, materials,
  weight_grams, origin, sku, image, tags, local_insight
)
VALUES
  ('harbor-weekender', 'harbor-weekender', 'Harbor Weekender', 'Bags', 22800, 'A waxed-canvas duffel that still looks right after a rainy ferry ride.', 'Forty-two liters, bridle-leather handles, and a pocket that fits a sweater without a packing cube. The canvas darkens where the rain hits and lightens again as it dries. We cut it in Portland and stitch the handles so the bag stands up when you set it down.', '18oz waxed canvas, bridle leather, solid brass hardware', 980, 'Portland, Oregon', 'CV-BAG-042', 'harbor-weekender.svg', ARRAY['bag', 'canvas', 'weekend', 'travel', 'duffel']::text[], 'Lead with the ferry test: it is the bag people buy when they are done replacing nylon duffels every other year. Mention the 42 liter size so they can picture a two-night trip, not a move.'),
  ('tide-merino', 'tide-merino', 'Tide Merino Crew', 'Knitwear', 16800, 'An 18-micron merino crew that is warm on the bluff and not itchy in a heated car.', 'Knitted in Oregon from extra-fine merino. The shoulder is set in so it sits under a shell without bunching, and the hem stays put when you reach for a bag in the overhead bin. It replaces a fleece for anyone who is tired of pilling.', '100% 18-micron merino wool', 240, 'Knitted in Oregon', 'CV-KNT-018', 'tide-merino.svg', ARRAY['wool', 'merino', 'sweater', 'knit', 'crew']::text[], 'This is the layer under the Weather Shell. If a shopper is choosing between fleece and wool, talk about the car ride home — merino does not overheat the way a pile jacket does.'),
  ('camp-enamel', 'camp-enamel', 'Camp Enamel Pair', 'Camp', 3600, 'Two speckled 12oz enamel mugs. The only matching set on the floor.', 'Rolled rims, a charcoal speckle, and a size that works for coffee or soup. They stack in the weekender''s end pocket. We sell them as a pair because one mug always ends up at someone else''s seat.', 'Speckled enamel on steel', 280, 'Finished in the United States', 'CV-CMP-012', 'camp-enamel.svg', ARRAY['camp', 'mug', 'enamel', 'gift', 'coffee']::text[], 'The easiest add-on in the store. Put it next to the Kiln Bottle: the bottle is for the trailhead, the enamel pair is for the table once you stop walking.'),
  ('drift-throw', 'drift-throw', 'Drift Wool Throw', 'Home', 18600, 'An undyed wool throw that lives on the couch and earns a place in the trunk.', 'Sixty by eighty inches, whipped edges, no dye. The wool still smells faintly like the mill when it arrives. It is heavy enough to matter on a deck in October and folds into the weekender when the plan changes.', 'Undyed wool, whipped cotton edge', 1400, 'Woven in the Pacific Northwest', 'CV-HME-060', 'drift-throw.svg', ARRAY['wool', 'blanket', 'throw', 'home']::text[], 'Shoppers who hesitate at the weight are the ones who should take it. Call out 60 by 80 so they do not picture a lap blanket, and mention it folds into the Harbor Weekender.'),
  ('beacon-lantern', 'beacon-lantern', 'Beacon Brass Lantern', 'Camp', 9400, 'A rechargeable brass lantern. A table light, not a flashlight.', 'Two hundred twenty lumens at the top, a low setting that runs about eight hours, and glass you can actually see through. The brass takes a thumbprint and keeps it. It charges on USB-C and sits flat, so it does not wander across a picnic table.', 'Brass, glass, USB-C rechargeable cell', 640, 'Assembled in Portland', 'CV-CMP-220', 'beacon-lantern.svg', ARRAY['camp', 'light', 'lantern', 'brass']::text[], 'Correct the flashlight assumption in the first sentence. The sale happens when someone pictures it on a table, not on a headlamp strap. Eight hours on low is the number to remember.'),
  ('salt-linen', 'salt-linen', 'Salt Linen Shirt', 'Apparel', 12800, 'An undyed linen field shirt for the hour when the wind drops and the sun stays.', 'European linen, a real collar, and mother-of-pearl buttons. It wrinkles. That is the point — it looks like you wore it outside. The cut is closer to a work shirt than a camp shirt, with a pocket that holds sunglasses without sagging.', '100% European linen, mother-of-pearl buttons', 210, 'Cut and sewn in Los Angeles', 'CV-APP-128', 'salt-linen.svg', ARRAY['linen', 'shirt', 'apparel', 'summer']::text[], 'Do not apologize for the wrinkles. Shoppers who want a crisp poplin are in the wrong store. Pair it with the cedar trees if they ask how to keep the collar from collapsing overnight.'),
  ('field-journal', 'field-journal', 'Field Notes Journal', 'Stationery', 4200, 'Ninety-six pages of graph paper, a leather cover, and a loop that holds the pencil.', 'Lay-flat binding so a map sketch does not fight the gutter. The leather is vegetable-tanned and unmarked on purpose. A cedar pencil rides in the loop; we include one and sell replacements at the counter.', 'Vegetable-tanned leather, graph paper, cedar pencil', 180, 'Bound in Portland', 'CV-STA-096', 'field-journal.svg', ARRAY['journal', 'gift', 'leather', 'stationery']::text[], 'A gift for someone who already owns too many blank notebooks. The lay-flat binding and the pencil loop are the two details that separate it from a diary. Price makes it an easy second item.'),
  ('kiln-bottle', 'kiln-bottle', 'Kiln Bottle', 'Camp', 4800, 'A 20oz insulated bottle with a cap you can open with cold hands.', 'Double-wall steel, a powder coat that does not chalk, and a loop that clips to the weekender. It holds heat through a trailhead wait. We tested the cap with gloves on because that is when people actually need water.', 'Double-wall stainless steel, powder coat', 340, 'Designed in Portland', 'CV-CMP-020', 'kiln-bottle.svg', ARRAY['bottle', 'camp', 'steel', 'coffee']::text[], 'Sell the cap, not the insulation. Every bottle claims to keep coffee hot. The reason this one comes back is that people can open it when their hands are numb.'),
  ('weather-shell', 'weather-shell', 'Weather Shell', 'Apparel', 29800, 'A waxed-cotton rain shell that does not sound like a plastic bag.', 'Unlined, raglan shoulders, taped seams, and a waxed cotton that sheds a steady rain. It is not a ski jacket. Rewax it once a season and it darkens in the creases the way a good jacket should. The hood goes over a cap, not a helmet.', 'Waxed cotton, taped seams, horn buttons', 720, 'Sewn in Seattle', 'CV-APP-298', 'weather-shell.svg', ARRAY['rain', 'jacket', 'shell', 'waxed', 'weather']::text[], 'The highest ticket on the floor, and the one people research before they walk in. Tell them it is unlined and that they will rewax it. If they want a membrane jacket, this is the wrong piece — say so.'),
  ('cedar-trees', 'cedar-trees', 'Cedar Shoe Trees', 'Care', 5400, 'Aromatic cedar, spring-loaded, sold as a pair. For the shoes you mean to keep.', 'Split toe, a spring that does not fight you, and cedar that actually smells like cedar for the first month. They are unfinished on purpose so the wood can take up moisture overnight. One size adjusts across most adult shoes.', 'Aromatic cedar, steel spring', 260, 'Turned in Vermont', 'CV-CRE-002', 'cedar-trees.svg', ARRAY['care', 'cedar', 'shoes', 'gift']::text[], 'A quiet gift and a practical add-on to the Salt Linen Shirt conversation — people who care about a collar usually care about their shoes. Mention they are unfinished cedar, not a lacquered souvenir.'),
  ('coast-glass', 'coast-glass', 'Coast Glass 8x25', 'Field', 17600, 'Compact fog-proof binoculars with enough reach for a far buoy.', 'Eight by twenty-five, roof prism, and a body that fits a jacket pocket without a case the size of a book. Nitrogen-filled so a cold morning on the river does not fog the glass. The strap is leather because nylon saws at a collar.', 'Optical glass, aluminum body, leather strap', 310, 'Assembled in Japan', 'CV-FLD-825', 'coast-glass.svg', ARRAY['field', 'binoculars', 'glass', 'coast']::text[], 'Shoppers compare these to a phone zoom and lose. Put them in someone''s hands and point at something specific — a buoy, a ridge — then mention the 310 gram weight so the pocket claim is believable.'),
  ('trail-socks', 'trail-socks', 'Trail Sock Three-Pack', 'Knitwear', 4200, 'The thing we reorder most. Cushion where the boot hits, not a club of a sock.', 'A merino blend with a cushioned sole and a plain leg. Three pairs, because one pair of good socks is a theory. They dry overnight on a radiator and do not slump into the shoe by noon.', 'Merino blend, cushioned sole', 150, 'Knitted in North Carolina', 'CV-KNT-003', 'trail-socks.svg', ARRAY['wool', 'socks', 'merino', 'gift', 'trail']::text[], 'Our reorder. Attach it to every weekender and every shell. The three-pack is the reason the price feels obvious — say ''three pairs'' before you say the number.');
COMMIT;
